&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience using tools like Copilot,&amp;nbsp;Storyblocks, ChatGPT/Claude, LinkedIn Sales Insights, industry research, etc.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
