&lt;p&gt;&lt;strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:300}&quot;&gt;Strategic Account Management&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
